mapper.select:
select l.log_id, l.member_id, m.phone, l.currency, l.biz_type, l.biz_id, l.amount,
       l.available_before, l.available_after, l.frozen_before, l.frozen_after,
       l.remark, l.create_time
from biz_wallet_log l
left join biz_member m on m.member_id = l.member_id

    and l.member_id = #{memberId}
    and l.currency = #{currency}
    and l.biz_type = #{bizType}
    and m.phone like concat('%', #{phone}, '%')

order by l.log_id desc

select l.log_id, l.member_id, m.phone, l.currency, l.biz_type, l.biz_id, l.amount,
       l.available_before, l.available_after, l.frozen_before, l.frozen_after,
       l.remark, l.create_time
from biz_wallet_log l
left join biz_member m on m.member_id = l.member_id
where l.member_id = #{memberId}
  and l.available_before <> l.available_after
and l.currency = #{currency}
and l.biz_type = #{bizType}
order by l.log_id desc
